ARCHIVOS = {'backend/app.py': [['@app.get("/api/dashboard/valor-inventario")\ndef api_dashboard_valor_inventario(usuario: dict = Depends(requiere_dashboard)):\n    """Valor del inventario (a costo de compra) por sucursal, y los 50\n    artículos que más valor representan en cada una."""\n    config = _config_microsip_o_error(usuario)\n    try:\n        resultado = microsip.obtener_valor_inventario_por_almacen(config)\n    except Exception as e:\n        raise HTTPException(status_code=400, detail=f"Error consultando Microsip (inventario): {e}")\n    return resultado', '@app.get("/api/dashboard/valor-inventario")\ndef api_dashboard_valor_inventario(usuario: dict = Depends(requiere_dashboard)):\n    """Valor del inventario (a costo de compra) por sucursal, y los 50\n    artículos que más valor representan en cada una."""\n    config = _config_microsip_o_error(usuario)\n    try:\n        resultado = microsip.obtener_valor_inventario_por_almacen(config)\n    except Exception as e:\n        raise HTTPException(status_code=400, detail=f"Error consultando Microsip (inventario): {e}")\n    return resultado\n\n\n@app.get("/api/dashboard/descuentos-pv")\ndef api_dashboard_descuentos_pv(fecha: Optional[str] = None, mes: Optional[str] = None, usuario: dict = Depends(requiere_dashboard)):\n    """Descuento total (en dinero) por sucursal, y los 50 descuentos más\n    altos otorgados en cada una, con el cliente y el monto del ticket."""\n    config = _config_microsip_o_error(usuario)\n    from datetime import date, datetime, timedelta\n    if mes:\n        try:\n            primer_dia = datetime.strptime(mes, "%Y-%m").date()\n        except ValueError:\n            raise HTTPException(status_code=400, detail="Mes inválido, usa el formato AAAA-MM")\n        fecha_inicio = primer_dia.isoformat()\n        fecha_fin_dt = date(primer_dia.year + 1, 1, 1) if primer_dia.month == 12 else date(primer_dia.year, primer_dia.month + 1, 1)\n        fecha_fin = fecha_fin_dt.isoformat()\n        etiqueta = mes\n    else:\n        if fecha:\n            try:\n                dia = datetime.strptime(fecha, "%Y-%m-%d").date()\n            except ValueError:\n                raise HTTPException(status_code=400, detail="Fecha inválida, usa el formato AAAA-MM-DD")\n        else:\n            dia = date.today()\n        fecha_inicio = dia.isoformat()\n        fecha_fin = (dia + timedelta(days=1)).isoformat()\n        etiqueta = fecha_inicio\n    try:\n        resultado = microsip.obtener_descuentos_pv(config, fecha_inicio, fecha_fin)\n    except Exception as e:\n        raise HTTPException(status_code=400, detail=f"Error consultando Microsip (Punto de Venta): {e}")\n    resultado["fecha"] = etiqueta\n    return resultado']], 'frontend/index.html': [["    let resumenValorInventario = null;\n    if (puedeVerFlotilla) {\n      try {\n        resumenValorInventario = await api('/api/dashboard/valor-inventario');\n      } catch (e) {\n        resumenValorInventario = null;\n      }\n    }", "    let resumenValorInventario = null;\n    if (puedeVerFlotilla) {\n      try {\n        resumenValorInventario = await api('/api/dashboard/valor-inventario');\n      } catch (e) {\n        resumenValorInventario = null;\n      }\n    }\n    let resumenDescuentosPv = null;\n    if (puedeVerFlotilla) {\n      try {\n        resumenDescuentosPv = await api(`/api/dashboard/descuentos-pv?fecha=${new Date().toISOString().slice(0, 10)}`);\n      } catch (e) {\n        resumenDescuentosPv = null;\n      }\n    }"], ['            <button class="secondary" style="width:100%; margin-top:14px; font-size:11px; padding:7px;" onclick="abrirDesgloseInventarioDashboard()">🔎 Ver desglose completo</button>\n          </div>\n        ` : \'\'}', '<button class="secondary" style="width:100%; margin-top:14px; font-size:11px; padding:7px;" onclick="abrirDesgloseInventarioDashboard()">🔎 Ver desglose completo</button>\n          </div>\n        ` : \'\'}\n        ${puedeVerFlotilla && resumenDescuentosPv ? `\n          <div class="dash-tarjeta">\n            <div class="dash-tarjeta-header">\n              <span class="dash-icono">🏷️</span>\n              <div>\n                <div class="dash-titulo">Descuentos otorgados</div>\n                <div class="dash-total">Hoy — $${resumenDescuentosPv.total_general.toLocaleString(\'es-MX\', {minimumFractionDigits:2})}</div>\n              </div>\n            </div>\n            <div style="margin-top:10px;">\n              ${resumenDescuentosPv.por_sucursal.length ? resumenDescuentosPv.por_sucursal.map(s => `\n                <div style="display:flex; justify-content:space-between; font-size:12px; margin-bottom:3px;">\n                  <span>${escapeHtml(s.sucursal)}</span>\n                  <span style="color:var(--text);">$${s.descuento_total.toLocaleString(\'es-MX\', {minimumFractionDigits:2})}</span>\n                </div>\n              `).join(\'\') : `<p style="font-size:12px; color:var(--muted);">Sin descuentos registrados hoy.</p>`}\n            </div>\n            <button class="secondary" style="width:100%; margin-top:14px; font-size:11px; padding:7px;" onclick="abrirDesgloseDescuentosDashboard()">🔎 Ver desglose completo</button>\n          </div>\n        ` : \'\'}'], ['function abrirDesgloseVentasPvDashboard() {', 'let PERIODO_DESCUENTOS_PV = \'dia\';\nlet DESCUENTOS_SUCURSAL_SELECCIONADA = null;\nlet DESCUENTOS_PAGINA = 0;\nlet DESCUENTOS_DATOS_ACTUALES = null;\n\nfunction abrirDesgloseDescuentosDashboard() {\n  document.getElementById(\'modalContent\').innerHTML = `\n    <button class="close-btn" onclick="cerrarModal()">cerrar</button>\n    <h2>🏷️ Descuentos otorgados en Punto de Venta</h2>\n    <div style="display:flex; justify-content:flex-end; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px;">\n      <button id="dashDescuentosTabDia" class="secondary" style="padding:4px 10px;" onclick="cambiarPeriodoDescuentos(\'dia\')">Día</button>\n      <button id="dashDescuentosTabMes" class="secondary" style="padding:4px 10px;" onclick="cambiarPeriodoDescuentos(\'mes\')">Mes</button>\n      <input id="dashDescuentosFecha" type="date" style="width:auto;" onchange="renderDescuentosDashboard()" />\n      <input id="dashDescuentosMes" type="month" style="width:auto; display:none;" onchange="renderDescuentosDashboard()" />\n    </div>\n    <div id="dashDescuentosContenido"><p style="font-size:12px; color:var(--muted);">Cargando…</p></div>\n  `;\n  abrirModal(\'admin\');\n  document.getElementById(\'dashDescuentosFecha\').value = new Date().toISOString().slice(0, 10);\n  document.getElementById(\'dashDescuentosMes\').value = new Date().toISOString().slice(0, 7);\n  cambiarPeriodoDescuentos(PERIODO_DESCUENTOS_PV);\n}\n\nfunction cambiarPeriodoDescuentos(periodo) {\n  PERIODO_DESCUENTOS_PV = periodo;\n  const esDia = periodo === \'dia\';\n  document.getElementById(\'dashDescuentosFecha\').style.display = esDia ? \'\' : \'none\';\n  document.getElementById(\'dashDescuentosMes\').style.display = esDia ? \'none\' : \'\';\n  const btnDia = document.getElementById(\'dashDescuentosTabDia\');\n  const btnMes = document.getElementById(\'dashDescuentosTabMes\');\n  btnDia.style.background = esDia ? \'var(--copper)\' : \'\';\n  btnDia.style.color = esDia ? \'#fff\' : \'\';\n  btnMes.style.background = !esDia ? \'var(--copper)\' : \'\';\n  btnMes.style.color = !esDia ? \'#fff\' : \'\';\n  renderDescuentosDashboard();\n}\n\nasync function renderDescuentosDashboard() {\n  const cont = document.getElementById(\'dashDescuentosContenido\');\n  if (!cont) return;\n  const query = PERIODO_DESCUENTOS_PV === \'dia\'\n    ? `fecha=${document.getElementById(\'dashDescuentosFecha\').value}`\n    : `mes=${document.getElementById(\'dashDescuentosMes\').value}`;\n  cont.innerHTML = \'<p style="font-size:12px; color:var(--muted);">Cargando…</p>\';\n  try {\n    const d = await api(`/api/dashboard/descuentos-pv?${query}`);\n    if (!d.por_sucursal.length) {\n      cont.innerHTML = `<p style="font-size:12px; color:var(--muted);">No hay descuentos registrados ${PERIODO_DESCUENTOS_PV === \'dia\' ? \'ese día\' : \'ese mes\'}.</p>`;\n      return;\n    }\n    if (DESCUENTOS_SUCURSAL_SELECCIONADA === null || !d.por_sucursal.some(s => s.sucursal_id === DESCUENTOS_SUCURSAL_SELECCIONADA)) {\n      DESCUENTOS_SUCURSAL_SELECCIONADA = d.por_sucursal[0].sucursal_id;\n      DESCUENTOS_PAGINA = 0;\n    }\n    DESCUENTOS_DATOS_ACTUALES = d;\n    cont.innerHTML = `\n      <div style="overflow-x:auto; margin-bottom:20px;">\n        <table class="users">\n          <thead><tr><th>Sucursal</th><th>Descuento total</th></tr></thead>\n          <tbody>\n            ${d.por_sucursal.map(s => `\n              <tr><td>${escapeHtml(s.sucursal)}</td><td>$${s.descuento_total.toLocaleString(\'es-MX\', {minimumFractionDigits:2})}</td></tr>\n            `).join(\'\')}\n          </tbody>\n          <tfoot><tr><td><b>Total general</b></td><td><b>$${d.total_general.toLocaleString(\'es-MX\', {minimumFractionDigits:2})}</b></td></tr></tfoot>\n        </table>\n      </div>\n\n      <h3 style="margin:0 0 8px; font-size:15px;">🏆 Top 50 descuentos más altos</h3>\n      <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:14px;" id="dashDescuentosSucursalBotones">\n        ${d.por_sucursal.map(s => `\n          <button class="secondary" style="padding:5px 12px; font-size:12px; ${s.sucursal_id === DESCUENTOS_SUCURSAL_SELECCIONADA ? \'background:var(--copper); color:#fff;\' : \'\'}" onclick="cambiarSucursalDescuentos(${s.sucursal_id})">${escapeHtml(s.sucursal)}</button>\n        `).join(\'\')}\n      </div>\n      <div id="dashDescuentosTopLista"></div>\n    `;\n    renderTopDescuentos();\n  } catch (e) {\n    cont.innerHTML = `<p style="font-size:12px; color:var(--copper);">${escapeHtml(e.message)}</p>`;\n  }\n}\n\nfunction cambiarSucursalDescuentos(sucursalId) {\n  DESCUENTOS_SUCURSAL_SELECCIONADA = sucursalId;\n  DESCUENTOS_PAGINA = 0;\n  const botones = document.getElementById(\'dashDescuentosSucursalBotones\');\n  if (botones) {\n    [...botones.children].forEach(btn => {\n      const esEste = btn.getAttribute(\'onclick\') === `cambiarSucursalDescuentos(${sucursalId})`;\n      btn.style.background = esEste ? \'var(--copper)\' : \'\';\n      btn.style.color = esEste ? \'#fff\' : \'\';\n    });\n  }\n  renderTopDescuentos();\n}\n\nfunction renderTopDescuentos() {\n  const cont = document.getElementById(\'dashDescuentosTopLista\');\n  if (!cont || !DESCUENTOS_DATOS_ACTUALES) return;\n  const sucursal = DESCUENTOS_DATOS_ACTUALES.por_sucursal.find(s => s.sucursal_id === DESCUENTOS_SUCURSAL_SELECCIONADA);\n  const lista = sucursal ? sucursal.top_descuentos : [];\n  const porPagina = 10;\n  const totalPaginas = Math.max(1, Math.ceil(lista.length / porPagina));\n  if (DESCUENTOS_PAGINA >= totalPaginas) DESCUENTOS_PAGINA = totalPaginas - 1;\n  const inicio = DESCUENTOS_PAGINA * porPagina;\n  const pagina = lista.slice(inicio, inicio + porPagina);\n  cont.innerHTML = `\n    <div style="overflow-x:auto;">\n      <table class="users">\n        <thead><tr><th>#</th><th>Cliente</th><th>Folio</th><th>Fecha / Hora</th><th>Descuento</th><th>Monto del ticket</th></tr></thead>\n        <tbody>\n          ${pagina.length ? pagina.map((v, i) => `\n            <tr>\n              <td>${inicio + i + 1}</td>\n              <td>${escapeHtml(v.cliente)}</td>\n              <td>${escapeHtml(v.folio || \'—\')}</td>\n              <td>${escapeHtml(v.fecha || \'—\')} ${escapeHtml(v.hora || \'\')}</td>\n              <td>$${v.descuento.toLocaleString(\'es-MX\', {minimumFractionDigits:2})}</td>\n              <td>$${v.monto.toLocaleString(\'es-MX\', {minimumFractionDigits:2})}</td>\n            </tr>\n          `).join(\'\') : `<tr><td colspan="6" class="empty-col">— sin descuentos en esta sucursal —</td></tr>`}\n        </tbody>\n      </table>\n    </div>\n    <div style="display:flex; justify-content:space-between; align-items:center; margin-top:10px;">\n      <button class="secondary" style="padding:5px 14px;" ${DESCUENTOS_PAGINA === 0 ? \'disabled\' : \'\'} onclick="cambiarPaginaDescuentos(-1)">← Anteriores 10</button>\n      <span style="font-size:12px; color:var(--muted);">Página ${DESCUENTOS_PAGINA + 1} de ${totalPaginas} (${lista.length} en total)</span>\n      <button class="secondary" style="padding:5px 14px;" ${DESCUENTOS_PAGINA >= totalPaginas - 1 ? \'disabled\' : \'\'} onclick="cambiarPaginaDescuentos(1)">Siguientes 10 →</button>\n    </div>\n  `;\n}\n\nfunction cambiarPaginaDescuentos(delta) {\n  DESCUENTOS_PAGINA += delta;\n  renderTopDescuentos();\n}\n\nfunction abrirDesgloseVentasPvDashboard() {']]}

MICROSIP_APPEND = '\n\n# =============================================================================\n# DASHBOARD: descuentos otorgados en Punto de Venta — usa DOCTOS_PV_DET\n# (DSCTO_ART + DSCTO_EXTRA, confirmados con datos reales como los campos que\n# sí traen el descuento en PESOS; PCTJE_DSCTO se confirmó vacío/0 siempre en\n# este Microsip) por sucursal y con el cliente de cada ticket.\n# =============================================================================\n\ndef obtener_descuentos_pv(config: dict, fecha_inicio: str, fecha_fin: str):\n    """Descuento total (en dinero) por sucursal entre fecha_inicio (incluida)\n    y fecha_fin (excluida), y los 50 descuentos más altos otorgados en cada\n    una, con el cliente y el monto del ticket."""\n    con = _conectar(config)\n    cur = con.cursor()\n\n    cur.execute("""\n        SELECT p.SUCURSAL_ID, COALESCE(s.NOMBRE, \'Sin sucursal\'), SUM(d.DSCTO_ART + d.DSCTO_EXTRA)\n        FROM DOCTOS_PV_DET d\n        JOIN DOCTOS_PV p ON p.DOCTO_PV_ID = d.DOCTO_PV_ID\n        LEFT JOIN SUCURSALES s ON s.SUCURSAL_ID = p.SUCURSAL_ID\n        WHERE p.FECHA >= ? AND p.FECHA < ? AND p.ESTATUS <> \'C\'\n        GROUP BY p.SUCURSAL_ID, s.NOMBRE\n    """, (fecha_inicio, fecha_fin))\n    totales = {}\n    for sucursal_id, nombre, descuento in cur.fetchall():\n        totales[sucursal_id] = {\n            "sucursal_id": sucursal_id,\n            "sucursal": (nombre or "Sin sucursal").strip(),\n            "descuento_total": float(descuento or 0),\n        }\n\n    cur.execute("""\n        SELECT p.SUCURSAL_ID, COALESCE(c.NOMBRE, \'Público en general\'),\n               p.FOLIO, p.FECHA, p.HORA, (d.DSCTO_ART + d.DSCTO_EXTRA), d.PRECIO_TOTAL_NETO\n        FROM DOCTOS_PV_DET d\n        JOIN DOCTOS_PV p ON p.DOCTO_PV_ID = d.DOCTO_PV_ID\n        LEFT JOIN CLIENTES c ON c.CLIENTE_ID = p.CLIENTE_ID\n        WHERE p.FECHA >= ? AND p.FECHA < ? AND p.ESTATUS <> \'C\' AND (d.DSCTO_ART + d.DSCTO_EXTRA) > 0\n        ORDER BY (d.DSCTO_ART + d.DSCTO_EXTRA) DESC\n    """, (fecha_inicio, fecha_fin))\n    filas = cur.fetchall()\n    con.close()\n\n    # Como la consulta ya viene ordenada de mayor a menor descuento, ir\n    # repartiendo cada fila en su sucursal y cortar en 50 mantiene el orden\n    # correcto dentro de cada sucursal sin tener que reordenar después.\n    por_sucursal_desc = {}\n    for sucursal_id, cliente, folio, fecha, hora, descuento, monto in filas:\n        lista = por_sucursal_desc.setdefault(sucursal_id, [])\n        if len(lista) >= 50:\n            continue\n        lista.append({\n            "cliente": (cliente or "Público en general").strip(),\n            "folio": folio,\n            "fecha": str(fecha)[:10] if fecha else None,\n            "hora": str(hora)[:8] if hora else None,\n            "descuento": float(descuento or 0),\n            "monto": float(monto or 0),\n        })\n\n    resultado = []\n    for sucursal_id, datos in sorted(totales.items(), key=lambda kv: -kv[1]["descuento_total"]):\n        datos = dict(datos)\n        datos["top_descuentos"] = por_sucursal_desc.get(sucursal_id, [])\n        resultado.append(datos)\n\n    total_general = sum(d["descuento_total"] for d in resultado)\n    return {"por_sucursal": resultado, "total_general": total_general}\n'


def leer(ruta):
    with open(ruta, "r", encoding="utf-8", newline=None) as f:
        return f.read()


def escribir(ruta, contenido):
    with open(ruta, "w", encoding="utf-8", newline="") as f:
        f.write(contenido)


def aplicar_reemplazos(ruta):
    reemplazos = ARCHIVOS[ruta]
    try:
        contenido = leer(ruta)
    except FileNotFoundError:
        print(f"[{ruta}] No encontre el archivo -- corre esto desde la carpeta del repo.")
        return False
    cambios = 0
    hubo_error = False
    for viejo, nuevo in reemplazos:
        if nuevo in contenido:
            continue
        if viejo not in contenido:
            print(f"[{ruta}] No encontre un bloque esperado (el archivo pudo haber cambiado). Avisale a Claude.")
            hubo_error = True
            continue
        contenido = contenido.replace(viejo, nuevo, 1)
        cambios += 1
    escribir(ruta, contenido)
    print(f"[{ruta}] {cambios} cambio(s) aplicado(s).")
    return not hubo_error


def aplicar_microsip():
    ruta = "backend/microsip.py"
    try:
        contenido = leer(ruta)
    except FileNotFoundError:
        print(f"[{ruta}] No encontre el archivo -- corre esto desde la carpeta del repo.")
        return False
    if MICROSIP_APPEND.strip() in contenido:
        print(f"[{ruta}] Ya estaba aplicado. No hace falta nada.")
        return True
    contenido = contenido + MICROSIP_APPEND
    escribir(ruta, contenido)
    print(f"[{ruta}] Funcion agregada al final del archivo.")
    return True


def main():
    ok = True
    ok = aplicar_microsip() and ok
    ok = aplicar_reemplazos("backend/app.py") and ok
    ok = aplicar_reemplazos("frontend/index.html") and ok

    if not ok:
        print()
        print("Algo no se pudo aplicar automaticamente. Avisale a Claude que mensaje salio, sin correr git add/commit todavia.")
        sys.exit(1)

    print()
    print("Todo listo. Ahora corre:")
    print("   git add backend/app.py backend/microsip.py frontend/index.html")
    print('   git commit -m "Dashboard: descuentos otorgados en Punto de Venta por sucursal"')
    print("   git push")


if __name__ == "__main__":
    main()
